// Tides Dice Studio - browser UI.  All geometry is generated by the local Python
// server; this file only edits the project, shows the exact export meshes and
// drives the workflow.
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const $ = (s, el = document) => el.querySelector(s);
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const clone = (o) => JSON.parse(JSON.stringify(o));

// ---------------------------------------------------------------- API ----
async function api(path, body, { raw = false } = {}) {
  const res = await fetch('/api/' + path, {
    method: 'POST',
    headers: { 'Content-Type': body instanceof ArrayBuffer ? 'application/octet-stream' : 'application/json' },
    body: body instanceof ArrayBuffer ? body : JSON.stringify(body || {}),
  });
  if (raw && res.ok) return res;
  const data = await res.json().catch(() => ({ error: `HTTP ${res.status}` }));
  if (!res.ok || data.error) throw new Error(data.error || `HTTP ${res.status}`);
  return data;
}

// -------------------------------------------------------------- state ----
const S = {
  config: null, project: null, results: {}, selected: 'd20', view: 'rendered', focus: 'set',
  history: [], future: [], lastLabel: null, lastTime: 0, baseline: {}, projectPath: null, dirty: false,
  pendingFont: null, depthShade: true, reqId: 0, report: null, resin: '#c9a227',
};
const DIE_LABEL = (d) => d.toUpperCase();

// ---------------------------------------------------------- messages ----
function msg(text, kind = 'info', action = null) {
  const box = $('#messages');
  const div = document.createElement('div');
  div.className = 'msg ' + kind;
  div.textContent = `[${new Date().toLocaleTimeString()}] ${text}`;
  if (action) {
    const b = document.createElement('button');
    b.textContent = action.label;
    b.onclick = action.fn;
    div.appendChild(b);
  }
  box.prepend(div);
  while (box.children.length > 60) box.lastChild.remove();
}

// ----------------------------------------------------------- history ----
function commit(newProject, label = 'edit', opts = {}) {
  if (newProject._regen) {
    // re-derive the family design from seed/style/density on the server (locks respected)
    delete newProject._regen;
    api('randomize', { project: newProject, scope: 'design' })
      .then((r) => commit(r.project, label, opts)).catch((e) => msg(e.message, 'err'));
    return;
  }
  const coalesce = !!opts.coalesce;
  const now = Date.now();
  if (!(coalesce && S.lastLabel === label && now - S.lastTime < 1500)) {
    S.history.push(S.project);
    if (S.history.length > 150) S.history.shift();
  }
  S.lastLabel = label; S.lastTime = now;
  S.future = [];
  S.project = newProject;
  S.dirty = true;
  afterProjectChange();
}
function undo() {
  if (!S.history.length) return;
  S.future.push(S.project);
  S.project = S.history.pop();
  S.lastLabel = null;
  afterProjectChange();
}
function redo() {
  if (!S.future.length) return;
  S.history.push(S.project);
  S.project = S.future.pop();
  S.lastLabel = null;
  afterProjectChange();
}
function edit(label, fn, opts) {
  const p = clone(S.project);
  fn(p);
  commit(p, label, opts);
}
function afterProjectChange() {
  $('#btn-undo').disabled = !S.history.length;
  $('#btn-redo').disabled = !S.future.length;
  $('#project-name').textContent = `${S.project.name}${S.dirty ? ' •' : ''}${S.projectPath ? '  —  ' + S.projectPath : ''}`;
  renderPanels();
  scheduleGenerate();
}

// --------------------------------------------------------- generation ----
let genTimer = null;
function scheduleGenerate(delay = 300) {
  clearTimeout(genTimer);
  genTimer = setTimeout(generate, delay);
}
async function generate() {
  // one request per die, in parallel: a slow die (e.g. the curved infinity D4)
  // never holds up the others, and each die appears as soon as it is ready
  const id = ++S.reqId;
  const proj = S.project;
  $('#busy').classList.remove('hidden');
  const errors = new Set();
  await Promise.all(S.config.dice.map(async (d) => {
    setDot(d, 'busy');
    try {
      const out = await api('generate', { project: proj, dice: [d] });
      if (id !== S.reqId) return; // a newer edit superseded this request
      const r = out.dice[d];
      S.results[d] = r;
      if (!S.baseline[d] && r.ok) S.baseline[d] = r.hash;
      await loadDie(d, r);
      if (id !== S.reqId) return;
      reportBuild([d]);
      refreshScene();
      if (d === S.selected) renderPanels(true);
    } catch (e) {
      if (id !== S.reqId) return;
      if (!errors.has(e.message)) { errors.add(e.message); msg(e.message, 'err'); }
      setDot(d, S.results[d] ? dotKind(S.results[d]) : 'err');
    }
  }));
  if (id === S.reqId) {
    $('#busy').classList.add('hidden');
    renderPanels(true);
  }
}
function dotKind(r) {
  if (!r.ok) return 'err';
  if (r.warnings.length || (r.outer_report && !r.outer_report.ok) || (r.blank_check && !r.blank_check.ok)) return 'warn';
  return 'ok';
}
let lastReported = {};
function reportBuild(dice = S.config.dice) {
  for (const d of dice) {
    const r = S.results[d];
    const key = r.hash;
    setDot(d, dotKind(r));
    if (lastReported[d] === key) continue;
    lastReported[d] = key;
    for (const e of r.errors) {
      const act = r.info.retry_available ? { label: 'Retry with safe geometry', fn: () => edit('safe mode', (p) => { p.dice[d].safe_mode = true; }) } : null;
      msg(e, 'err', act);
    }
    for (const w of r.warnings) msg(`${DIE_LABEL(d)}: ${w}`, 'warn');
    if (r.ok && r.outer_report && !r.outer_report.ok) msg(`${DIE_LABEL(d)} mesh: ${r.outer_report.issues.join('; ')}`, 'err');
  }
}

// -------------------------------------------------------------- three ----
const canvas = $('#three');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, preserveDrawingBuffer: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.localClippingEnabled = true;
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1b1e25);
const camera = new THREE.PerspectiveCamera(35, 1, 0.5, 5000);
camera.position.set(0, -170, 120);
camera.up.set(0, 0, 1);
const controls = new OrbitControls(camera, canvas);
controls.enableDamping = true;
controls.screenSpacePanning = true;
scene.add(new THREE.HemisphereLight(0xffffff, 0x303040, 0.8));
const key = new THREE.DirectionalLight(0xffffff, 1.6); key.position.set(60, -80, 140); scene.add(key);
const rim = new THREE.DirectionalLight(0x9fb8ff, 0.7); rim.position.set(-120, 90, 40); scene.add(rim);
// headlight: follows the camera, offset up-left so engraved walls always cast visible shading
const head = new THREE.DirectionalLight(0xffffff, 1.3);
head.position.set(-0.5, 0.7, 1);
camera.add(head); camera.add(head.target); head.target.position.set(0, 0, -1);
scene.add(camera);
const grid = new THREE.GridHelper(400, 40, 0x2c3140, 0x232733);
grid.rotation.x = Math.PI / 2; grid.position.z = -14; scene.add(grid);

// set layout: two rows; spacing follows each die's real size (rollers can be long)
const ROWS = [['d4', 'd6', 'd8', 'd10'], ['d12', 'd20', 'd100']];
function isRoller(d) { return S.results[d]?.ok && S.results[d].info.shape_kind === 'roller'; }
function dieExtent(d) {
  const o = dieObjs[d];
  if (!o || !o.outerGeo) return [20, 20];
  o.outerGeo.computeBoundingBox();
  const s = o.outerGeo.boundingBox.getSize(new THREE.Vector3());
  return isRoller(d) ? [s.z, s.y] : [Math.max(s.x, s.y), Math.max(s.x, s.y)];  // rollers lie along x
}
function layoutPositions() {
  const pos = {};
  const rowH = ROWS.map((row) => Math.max(...row.map((d) => dieExtent(d)[1])));
  const rowY = [rowH[0] / 2 + 5, -(rowH[1] / 2 + 5)];
  ROWS.forEach((row, ri) => {
    const widths = row.map((d) => dieExtent(d)[0]);
    const total = widths.reduce((a, b) => a + b, 0) + 10 * (row.length - 1);
    let x = -total / 2;
    row.forEach((d, i) => { pos[d] = [x + widths[i] / 2, rowY[ri]]; x += widths[i] + 10; });
  });
  return pos;
}
// rollers are shown lying on a side, as they come to rest (side 0 down, the side read on top up)
const ROLLER_POSE = new THREE.Euler(0, Math.PI / 2, 0);
const geoCache = new Map();
const dieObjs = {}; // d -> {group, outer, blank, baseline, hash}

async function fetchGeometry(hash, part) {
  const k = hash + ':' + part;
  if (geoCache.has(k)) return geoCache.get(k);
  const res = await fetch(`/api/mesh/${hash}?part=${part}`);
  if (!res.ok) throw new Error(`mesh ${part} unavailable`);
  const buf = await res.arrayBuffer();
  const dv = new DataView(buf);
  const nv = dv.getUint32(0, true), nt = dv.getUint32(4, true);
  const pos = new Float32Array(buf, 8, nv * 3);
  const idx = new Uint32Array(buf, 8 + nv * 12, nt * 3);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setIndex(new THREE.BufferAttribute(idx, 1));
  g.computeBoundingSphere();
  geoCache.set(k, g);
  if (geoCache.size > 120) geoCache.delete(geoCache.keys().next().value);
  return g;
}

async function loadDie(d, r) {
  let o = dieObjs[d];
  if (!o) {
    o = dieObjs[d] = { group: new THREE.Group(), hash: null, outerGeo: null, blankGeo: null, baseGeo: null };
    o.group.userData.die = d;
    scene.add(o.group);
  }
  if (!r.ok) { o.hash = null; return; }
  if (o.hash === r.hash) return;
  o.outerGeo = await fetchGeometry(r.hash, 'outer');
  addDepthColors(o.outerGeo, r.planes);
  o.blankGeo = await fetchGeometry(r.hash, 'blank');
  o.hash = r.hash;
  updateThumb(d);
}

// Tint each vertex by its real depth below the die's convex hull (min distance to the
// outer face planes).  This visualises the actual recess geometry - nothing that is not
// in the STL - so engravings stay readable even when viewed straight on.
function addDepthColors(g, planes) {
  if (g.getAttribute('color') || !planes) return;
  const pos = g.getAttribute('position');
  const col = new Float32Array(pos.count * 3);
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    let depth = Infinity;
    for (const [nx, ny, nz, off] of planes) depth = Math.min(depth, off - (nx * x + ny * y + nz * z));
    const t = Math.min(1, Math.max(0, depth / 0.8));
    const c = 1 - 0.68 * t;
    col[i * 3] = col[i * 3 + 1] = col[i * 3 + 2] = c;
  }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
}
function resinMaterial(extra = {}) {
  return new THREE.MeshStandardMaterial({ color: S.resin, roughness: 0.38, metalness: 0.08, flatShading: true, vertexColors: S.depthShade, ...extra });
}

async function refreshScene() {
  const layout = layoutPositions();
  for (const d of S.config.dice) {
    const o = dieObjs[d];
    if (!o) continue;
    o.group.clear();
    const visible = S.focus === 'set' || d === S.selected;
    o.group.visible = visible && !!o.hash;
    const pos = S.focus === 'set' ? (layout[d] || [0, 0]) : [0, 0];
    o.group.position.set(pos[0], pos[1], 0);
    o.group.rotation.copy(isRoller(d) ? ROLLER_POSE : new THREE.Euler());
    if (!o.hash || !visible) continue;
    const selected = d === S.selected && S.focus === 'set';
    const emissive = selected ? 0x2a1f00 : 0x000000;
    const v = S.view;
    if (v === 'rendered' || v === 'compare') {
      o.group.add(new THREE.Mesh(o.outerGeo, resinMaterial({ emissive })));
    } else if (v === 'wireframe') {
      o.group.add(new THREE.Mesh(o.outerGeo, resinMaterial({ emissive, transparent: true, opacity: 0.35 })));
      o.group.add(new THREE.Mesh(o.outerGeo, new THREE.MeshBasicMaterial({ color: 0xe8e8e8, wireframe: true })));
    } else if (v === 'validation') {
      const rep = S.results[d].outer_report;
      const good = rep && rep.ok;
      o.group.add(new THREE.Mesh(o.outerGeo, new THREE.MeshStandardMaterial({ color: good ? 0x3fa36e : 0xcc8833, flatShading: true, side: THREE.FrontSide, emissive })));
      // inward-facing triangles would show in red
      o.group.add(new THREE.Mesh(o.outerGeo, new THREE.MeshBasicMaterial({ color: 0xff2020, side: THREE.BackSide })));
      o.group.add(new THREE.LineSegments(new THREE.EdgesGeometry(o.outerGeo, 25), new THREE.LineBasicMaterial({ color: 0x0b0d10 })));
    } else if (v === 'blank' || v === 'cutaway' || v === 'blankonly') {
      if (v !== 'blankonly') {
        const clip = v === 'cutaway' ? [new THREE.Plane(new THREE.Vector3(-1, 0, 0), pos[0])] : [];
        o.group.add(new THREE.Mesh(o.outerGeo, resinMaterial({
          transparent: v === 'blank', opacity: v === 'blank' ? 0.22 : 1, depthWrite: v !== 'blank',
          side: THREE.DoubleSide, clippingPlanes: clip, emissive,
        })));
        if (v === 'cutaway') {
          o.group.add(new THREE.Mesh(o.outerGeo, new THREE.MeshBasicMaterial({ color: 0x5a4a10, side: THREE.BackSide, clippingPlanes: clip })));
        }
      }
      o.group.add(new THREE.Mesh(o.blankGeo, new THREE.MeshStandardMaterial({ color: 0x4aa3df, roughness: 0.5, flatShading: true })));
      if (v !== 'blankonly') o.group.add(new THREE.LineSegments(new THREE.EdgesGeometry(o.blankGeo, 10), new THREE.LineBasicMaterial({ color: 0x1b4e72 })));
    }
    if (v === 'compare' && d === S.selected) {
      const bh = S.baseline[d];
      if (bh && bh !== o.hash) {
        try {
          const bg = await fetchGeometry(bh, 'outer');
          const m = new THREE.Mesh(bg, new THREE.MeshStandardMaterial({ color: 0x8a8f9c, flatShading: true, roughness: 0.6 }));
          m.position.x = -(o.outerGeo.boundingSphere.radius * 2.3);
          o.group.add(m);
        } catch { msg('baseline mesh no longer cached; set a new baseline', 'warn'); }
      }
    }
  }
  updateInfo();
  renderFaceBar();
}

function frameView() {
  const box = new THREE.Box3();
  for (const d of S.config.dice) {
    const o = dieObjs[d];
    if (o && o.group.visible) box.expandByObject(o.group);
  }
  if (box.isEmpty()) return;
  const c = box.getCenter(new THREE.Vector3());
  const r = box.getSize(new THREE.Vector3()).length() / 2;
  const dist = r / Math.sin(THREE.MathUtils.degToRad(camera.fov / 2)) * 0.95;
  controls.target.copy(c);
  camera.up.set(0, 0, 1);
  camera.position.copy(c).add(new THREE.Vector3(0, -0.72, 0.62).normalize().multiplyScalar(dist));
  controls.update();
}

function lookAtFace(face) {
  const o = dieObjs[S.selected];
  o.group.updateMatrixWorld(true);
  const q = o.group.getWorldQuaternion(new THREE.Quaternion());
  const c = o.group.localToWorld(new THREE.Vector3(...face.center));
  const n = new THREE.Vector3(...face.normal).applyQuaternion(q);
  controls.target.copy(c);
  camera.up.copy(new THREE.Vector3(...face.up).applyQuaternion(q)); // numerals appear upright while inspecting
  camera.position.copy(c).add(n.multiplyScalar(45));
  camera.lookAt(c);
  controls.update();
}

function resize() {
  const el = $('#viewport');
  const w = el.clientWidth, h = el.clientHeight;
  renderer.setSize(w, h, false);
  camera.aspect = w / Math.max(h, 1);
  camera.updateProjectionMatrix();
}
window.addEventListener('resize', resize);
(function loop() { controls.update(); renderer.render(scene, camera); requestAnimationFrame(loop); })();

// click selection (ignore drags)
let downAt = null;
canvas.addEventListener('pointerdown', (e) => { downAt = [e.clientX, e.clientY]; });
canvas.addEventListener('pointerup', (e) => {
  if (!downAt || Math.hypot(e.clientX - downAt[0], e.clientY - downAt[1]) > 4 || e.button !== 0) return;
  const r = canvas.getBoundingClientRect();
  const ndc = new THREE.Vector2(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
  const ray = new THREE.Raycaster();
  ray.setFromCamera(ndc, camera);
  const hits = ray.intersectObjects(Object.values(dieObjs).map((o) => o.group), true);
  if (hits.length) {
    let obj = hits[0].object;
    while (obj && !obj.userData.die) obj = obj.parent;
    if (obj) selectDie(obj.userData.die);
  }
});

// thumbnails rendered from the real export mesh
const thumbRenderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true, alpha: true });
thumbRenderer.setSize(120, 120);
const thumbScene = new THREE.Scene();
thumbScene.add(new THREE.HemisphereLight(0xffffff, 0x303040, 1.2));
const tk = new THREE.DirectionalLight(0xffffff, 1.5); tk.position.set(40, -60, 90); thumbScene.add(tk);
const thumbCam = new THREE.PerspectiveCamera(30, 1, 1, 1000);
thumbCam.up.set(0, 0, 1);
function updateThumb(d) {
  const o = dieObjs[d];
  if (!o || !o.outerGeo) return;
  const m = new THREE.Mesh(o.outerGeo, resinMaterial());
  if (isRoller(d)) m.rotation.copy(ROLLER_POSE);
  thumbScene.add(m);
  const r = o.outerGeo.boundingSphere.radius;
  thumbCam.position.set(r * 1.6, -r * 2.6, r * 2.1);
  thumbCam.lookAt(0, 0, 0);
  thumbRenderer.render(thumbScene, thumbCam);
  thumbScene.remove(m);
  const img = $(`#thumb-${d}`);
  if (img) img.src = thumbRenderer.domElement.toDataURL();
}

// --------------------------------------------------------- die list ----
function buildDiceList() {
  const el = $('#dice-list');
  el.innerHTML = '';
  for (const d of S.config.dice) {
    const card = document.createElement('div');
    card.className = 'die-card';
    card.id = `card-${d}`;
    card.innerHTML = `<img id="thumb-${d}" alt="${d}"><div class="lbl">${DIE_LABEL(d)}</div><span class="dot" id="dot-${d}"></span>`;
    card.onclick = () => selectDie(d);
    el.appendChild(card);
  }
}
function setDot(d, k) { const e = $(`#dot-${d}`); if (e) e.className = 'dot ' + k; }
function selectDie(d) {
  S.selected = d;
  document.querySelectorAll('.die-card').forEach((c) => c.classList.toggle('sel', c.id === `card-${d}`));
  refreshScene();
  if (S.focus === 'die') frameView();
  renderPanels();
}

function updateInfo() {
  const r = S.results[S.selected];
  const el = $('#vp-info');
  if (!r) { el.innerHTML = ''; return; }
  const d = S.selected;
  const lines = [`<b>${DIE_LABEL(d)}</b> ${r.ok ? '' : '<span class="err-text">build failed</span>'}`];
  if (r.ok) {
    const o = r.outer_report, b = r.blank_report, bc = r.blank_check;
    lines.push(`numerals ${r.info.numeral_height_mm} mm tall (max ${r.info.numeral_max_height_mm}) · engraving ${r.info.engrave_depth_mm} mm`);
    lines.push(esc(shapeLabel(d, r.info.shape)) + ' — ' + esc(restText(d)));
    if (S.view === 'validation' || S.view === 'wireframe') {
      lines.push(`mesh: ${o.triangles} triangles · ${o.watertight ? 'watertight' : 'OPEN'} · winding ${o.winding_consistent ? 'consistent' : 'BAD'} · ${o.components} piece · self-intersections ${o.self_intersections} · degenerate ${o.degenerate_triangles}`);
      lines.push(`volume ${o.volume_mm3.toFixed(1)} mm³ · ${o.ok ? '<span class="ok-text">valid</span>' : '<span class="err-text">' + esc(o.issues.join('; ')) + '</span>'}`);
    }
    if (['blank', 'cutaway', 'blankonly'].includes(S.view)) {
      lines.push(`blank: clearance ${bc.clearance_mm} mm (${bc.reference.replaceAll('_', ' ')}) · measured min gap <b>${bc.measured_min_gap_mm.toFixed(3)} mm</b>`);
      lines.push(`blank volume ${bc.volume_mm3.toFixed(1)} mm³ · min thickness ${bc.min_thickness_mm.toFixed(2)} mm · ${bc.ok && b.ok ? '<span class="ok-text">fits</span>' : '<span class="err-text">' + esc([...bc.issues, ...b.issues].join('; ')) + '</span>'}`);
      lines.push('<span style="color:#4aa3df">■</span> blank (separate STL) inside the outer die');
    }
    if (S.view === 'compare') lines.push(S.baseline[d] && S.baseline[d] !== r.hash ? 'grey = baseline (left), resin = current' : 'no changes since the baseline');
  } else lines.push(esc(r.errors.join(' ')));
  el.innerHTML = lines.join('<br>');
}

function renderFaceBar() {
  const el = $('#face-bar');
  const r = S.results[S.selected];
  el.innerHTML = '';
  if (!r || !r.ok) return;
  const t = document.createElement('span');
  t.className = 'hint'; t.textContent = 'Inspect face:';
  el.appendChild(t);
  for (const f of r.faces) {
    const b = document.createElement('button');
    b.textContent = f.labels.join('/') || '?';
    b.title = `face ${f.tag}`;
    b.onclick = () => { if (S.focus !== 'die') { S.focus = 'die'; $('#focus-mode').value = 'die'; refreshScene(); } lookAtFace(f); };
    el.appendChild(b);
  }
}

// ------------------------------------------------------------ panels ----
function h(tag, attrs = {}, ...kids) {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k.startsWith('on')) e.addEventListener(k.slice(2), v);
    else if (k === 'html') e.innerHTML = v;
    else if (v === true) e.setAttribute(k, '');
    else if (v !== false && v != null) e.setAttribute(k, v);
  }
  for (const k of kids.flat()) if (k != null) e.append(k.nodeType ? k : document.createTextNode(k));
  return e;
}
function group(title, ...kids) { return h('div', { class: 'group' }, h('h3', {}, title), ...kids); }
function sliderRow(label, value, min, max, step, onChange, { unit = '', title = '', lockKey = null } = {}) {
  const val = h('span', { class: 'val' }, fmt(value, step) + unit);
  const input = h('input', { type: 'range', min, max, step, value });
  input.addEventListener('input', () => { val.textContent = fmt(+input.value, step) + unit; onChange(+input.value, true); });
  input.addEventListener('change', () => onChange(+input.value, false));
  const kids = [h('label', { title }, label), val, h('div', { class: 'slider' }, input)];
  if (lockKey) kids.unshift(lockToggle(lockKey));
  return h('div', { class: 'row' + (lockKey ? ' lockable' : '') }, ...kids);
}
function fmt(v, step) { const dp = step >= 1 ? 0 : Math.min(3, String(step).split('.')[1]?.length || 2); return Number(v).toFixed(dp); }
function numRow(label, value, min, max, step, onChange, { title = '' } = {}) {
  const input = h('input', { type: 'number', min, max, step, value: value ?? '' });
  input.addEventListener('change', () => onChange(input.value === '' ? null : +input.value));
  return h('div', { class: 'row' }, h('label', { title }, label), input);
}
function selectRow(label, value, options, onChange, { lockKey = null, title = '' } = {}) {
  const sel = h('select', {}, ...options.map(([v, t]) => h('option', { value: v, selected: v === value }, t)));
  sel.addEventListener('change', () => onChange(sel.value));
  const kids = [h('label', { title }, label), sel];
  if (lockKey) kids.unshift(lockToggle(lockKey));
  return h('div', { class: 'row' + (lockKey ? ' lockable' : '') }, ...kids);
}
function checkRow(label, value, onChange, title = '') {
  const cb = h('input', { type: 'checkbox', checked: !!value });
  cb.addEventListener('change', () => onChange(cb.checked));
  return h('div', { class: 'row' }, h('label', { title }, label), cb);
}
function lockToggle(key) {
  const on = S.project.locks.includes(key);
  return h('span', {
    class: 'lock' + (on ? ' on' : ''), title: on ? 'Locked: kept when randomizing' : 'Unlocked: changes when randomizing',
    onclick: () => edit('lock', (p) => { p.locks = on ? p.locks.filter((k) => k !== key) : [...p.locks, key]; }),
  }, on ? '🔒' : '🔓');
}
function btn(text, fn, attrs = {}) { return h('button', { ...attrs, onclick: fn }, text); }

let lastPanelSig = '';
function renderPanels(onlyStatus = false) {
  if (onlyStatus && document.activeElement && document.activeElement.type === 'range') return;
  const sig = JSON.stringify([S.project, S.selected, S.pendingFont && S.pendingFont.asset.id, S.results[S.selected]?.hash]);
  if (sig === lastPanelSig && onlyStatus) return;
  lastPanelSig = sig;
  const scroll = Object.fromEntries([...document.querySelectorAll('.tab')].map((t) => [t.id, t.scrollTop]));
  renderDesign(); renderNumbers(); renderLogo(); renderBlank(); renderExport();
  for (const [id, s] of Object.entries(scroll)) $('#' + id).scrollTop = s;
  document.querySelectorAll('.die-card').forEach((c) => c.classList.toggle('sel', c.id === `card-${S.selected}`));
}

// ---- design tab
function shapeLabel(d, fam) { return S.config.families[d][fam]?.label || fam; }
function restText(d) {
  const r = S.results[d];
  if (!r || !r.ok) return '';
  const i = r.info, rest = i.rest || {};
  if (i.shape_kind === 'roller') {
    return `Rolls like a pencil and lands only on its ${i.faces} numbered sides (all ${rest.end_facets} end facets tip over); read the side facing up · ${i.length_mm} mm tip to tip`;
  }
  if (i.shape_kind === 'curved') return `Curved roller: rests on one of its 4 curved faces; ${rest.reading} · ${i.length_mm} mm tip to tip`;
  return `Lands on any face (all faces congruent) · ${i.length_mm} mm longest dimension`;
}
function renderDesign() {
  const p = S.project, d = S.selected, el = $('#tab-design');
  el.innerHTML = '';
  const cfg = S.config;
  el.append(group('Set',
    selectRow('Style preset', p.style, Object.entries(cfg.styles), (v) => edit('style', (q) => { q.style = v; regenDesignInto(q); })),
    sliderRow('Shape variation', p.density, 0, 1, 0.05, (v, live) => { if (!live) edit('density', (q) => { q.density = v; regenDesignInto(q); }); }, { title: 'how far proportions may move away from each shape\'s natural proportions' }),
    numRow('Random seed', p.seed, 1, 999999999, 1, (v) => v && edit('seed', (q) => { q.seed = Math.round(v); regenDesignInto(q); }), { title: 'the same seed, style and variation always reproduce the same set' }),
    designControl(cfg.design_schema.find((s) => s.key === 'size_scale')),
    h('div', { class: 'btns' },
      btn('🎲 Randomize set', randomizeSet, { title: 'new seed; locked shapes/proportions are kept' }),
      btn('↺ Reset set', () => op('reset_set'), { class: 'danger', title: 'discard all per-die changes' })),
    h('div', { class: 'hint' }, 'Shapes are either fair face-landing solids (all faces congruent) or rollers (crystals, shards, gems, the infinity D4) that can only come to rest on their numbered sides; the rest analysis checks this physically. The only cuts are the engraved numbers. 🔒 keeps a value when randomizing.'),
  ));
  const dd = p.dice[d];
  const eff = effectiveDesign(d);
  const fam = eff[`${d}_shape`];
  const shapeSchema = cfg.design_schema.find((s) => s.key === `${d}_shape`);
  const params = cfg.design_schema.filter((s) => s.die === d && s.family === fam);
  const meaning = cfg.size_meaning[d][fam];
  el.append(group(`Selected die: ${DIE_LABEL(d)}`,
    designControl(shapeSchema, fam),
    ...(params.length ? params.map((s) => designControl(s, eff[s.key])) : [h('div', { class: 'hint' }, 'regular solid: no proportion parameters')]),
    numRow(`Size (${meaning}, mm)`, dd.size_mm ?? cfg.default_sizes[d][fam], 8, 40, 0.5, (v) => edit('size', (q) => { q.dice[d].size_mm = v; })),
    h('div', { class: 'hint' }, restText(d)),
    h('div', { class: 'btns' },
      btn('🎲 Regenerate this die', () => op('die'), { title: 'new random shape for this die only' }),
      btn('↺ Reset die', () => op('reset_die'), { class: 'danger' })),
    h('div', { class: 'hint' }, `variant ${dd.variant}${dd.safe_mode ? ' · SAFE GEOMETRY MODE' : ''}`),
    dd.safe_mode ? btn('Leave safe geometry mode', () => edit('safe', (q) => { q.dice[d].safe_mode = false; })) : null,
  ));
  const rows = cfg.dice.map((x) => {
    const e = effectiveDesign(x);
    const f = e[`${x}_shape`];
    const ps = cfg.design_schema.filter((s) => s.die === x && s.family === f);
    const len = S.results[x]?.ok ? `${S.results[x].info.length_mm} mm` : '';
    return `<tr${x === d ? ' style="color:var(--accent)"' : ''}><td>${DIE_LABEL(x)}</td><td>${esc(shapeLabel(x, f))}</td><td>${ps.map((s) => Number(e[s.key]).toFixed(2)).join(' / ') || '—'}</td><td>${len}</td></tr>`;
  }).join('');
  el.append(group('All shapes in this set', h('div', { html: `<table class="rep"><tr><th>die</th><th>shape</th><th>proportions</th><th>length</th></tr>${rows}</table>` })));
}
function effectiveDesign(d) {
  const p = S.project;
  const r = S.results[d];
  return { ...p.design, ...(r && r.ok && r.info.design ? r.info.design : {}), ...p.dice[d].design_overrides };
}
function designControl(s, value) {
  if (value === undefined) value = S.project.design[s.key];
  const set = (v) => {
    edit('design:' + s.key, (q) => {
      // per-die keys are stored as overrides of that die (they win over its random variant)
      if (s.die) q.dice[s.die].design_overrides[s.key] = v;
      else q.design[s.key] = v;
    }, { coalesce: true });
  };
  if (s.type === 'choice') return selectRow(s.label, value, s.choices.map((c) => [c, (s.labels && s.labels[c]) || c]), set, { lockKey: s.key });
  return sliderRow(s.label, value, s.min, s.max, s.step, (v, live) => { if (!live) set(v); }, { lockKey: s.key });
}
function regenDesignInto(q) { q._regen = true; }
async function op(scope) {
  try {
    const out = await api('randomize', { project: S.project, scope, die: S.selected });
    commit(out.project, scope);
    msg(`${{ set: 'Randomized set', die: `Regenerated ${DIE_LABEL(S.selected)}`, reset_die: `Reset ${DIE_LABEL(S.selected)}`, reset_set: 'Reset set', design: 'Design regenerated' }[scope]}`, 'ok');
  } catch (e) { msg(e.message, 'err'); }
}
async function randomizeSet() { await op('set'); }

