let fontPrevKey = '';
async function loadFontPreview(assetId, weight, embolden) {
  const k = [assetId, weight, embolden].join('|');
  const box = $('#font-preview');
  if (k === fontPrevKey && box && box.dataset.html) { box.innerHTML = box.dataset.html; return; }
  fontPrevKey = k;
  try {
    const r = await api('font_preview', { asset_id: assetId || null, weight, embolden_mm: embolden });
    const svg = r.shapes.map((s) => `<svg viewBox="${s.bbox[0] - 1} ${s.bbox[1] - 1} ${s.bbox[2] + 2} ${s.bbox[3] + 2}" style="height:${s.text.length > 2 ? 54 : 44}px;width:auto;display:inline-block;margin-right:8px"><path d="${s.path}" fill="#2a2216" fill-rule="evenodd"/></svg>`).join('');
    const html = `<div class="hint" style="color:#555">${esc(r.name)} — actual cut outlines</div>${svg}`;
    const b = $('#font-preview');
    if (b) { b.innerHTML = html; b.dataset.html = html; }
  } catch (e) { const b = $('#font-preview'); if (b) b.innerHTML = `<span class="err-text">${esc(e.message)}</span>`; }
}
async function uploadFile(file, kind) {
  const buf = await file.arrayBuffer();
  return api(`upload?kind=${kind}&name=${encodeURIComponent(file.name)}`, buf);
}
$('#file-font').addEventListener('change', async (e) => {
  const f = e.target.files[0]; e.target.value = '';
  if (!f) return;
  try { S.pendingFont = await uploadFile(f, 'font'); fontPrevKey = ''; renderPanels(); msg(`Font ${f.name} loaded — check the preview, then apply`, 'ok'); }
  catch (err) { msg(`Font import failed: ${err.message}`, 'err'); }
});
async function importBundledFont(name) {
  try { S.pendingFont = await api('bundled_font', { name }); fontPrevKey = ''; renderPanels(); }
  catch (err) { msg(err.message, 'err'); }
}

